/bin/bash -lc "PYTHONDONTWRITEBYTECODE=1 PYTHONPATH=lib python - <<'PY'
from ansible.module_utils.facts.hardware.aix import AIXHardware

class Module:
    def run_command(self, command):
        if command == '/usr/sbin/lsdev -Cc processor':
            return 0, ''.join('proc%d Available 00-00 Processor\\n' % i for i in range(12)), ''
        if command.endswith(' -a type'):
            return 0, 'type PowerPC_POWER7 Processor type False\\n', ''
        if command.endswith(' -a smt_threads'):
            return 0, 'smt_threads 4 SMT threads False\\n', ''
        raise AssertionError(command)

print(AIXHardware(Module()).get_cpu_facts())
PY"

